function startAudit(){if(mastery.auditDraft?.seed){audit=null;go('audit');return;}const n=(mastery.assessmentRuns||0)+1;const seed=Date.now()%1000000+n*137;const qs=buildAssessment(seed);audit={seed,questions:qs,index:0,answers:[],value:null,confidence:'unsure'};mastery.auditDraft={seed,index:0,answers:[]};saveMastery();go('audit');}
function renderAudit(){if(!audit){if(mastery.auditDraft?.seed){const d=mastery.auditDraft;audit={seed:d.seed,questions:buildAssessment(d.seed),index:Math.min(11,d.index||0),answers:d.answers||[],value:null,confidence:'unsure'};}else{audit={seed:1,questions:buildAssessment(1),index:0,answers:[],value:null,confidence:'unsure'};}}const q=audit.questions[audit.index],j=audit.index,fill=100*j/audit.questions.length;
 return `<main class="view studio studio-audit"><div class="assessment-bar"><button class="round-close" data-act="audit-exit" aria-label="Выйти">×</button><span>SKILL CHECK <i>·</i> БЕЗ ТАЙМЕРА</span><b>${String(j+1).padStart(2,'0')} / 12</b></div><div class="audit-progress"><i style="width:${fill}%"></i></div><div class="audit-content"><span class="studio-kicker"><i></i> ${esc(DOMAINS.find(d=>d.id===q.domain)?.name.toUpperCase()||'AI')}</span><h1>${esc(q.text)}</h1>${q.code?`<pre class="audit-code">${esc(q.code)}</pre>`:''}${q.type==='choice'?`<div class="audit-answers">${q.options.map((x,k)=>`<button data-act="audit-choice" data-choice="${k}" class="audit-opt ${audit.value===k?'chosen':''}"><span>${'ABCD'[k]}</span><strong>${esc(x)}</strong><i>↗</i></button>`).join('')}</div>`:`<div class="audit-write"><label for="audit-input">ТВОЙ ОТВЕТ</label><input id="audit-input" type="text" autocomplete="off" spellcheck="false" placeholder="Введи точный результат" value="${esc(audit.value??'')}"><small>Пиши вывод программы или число, а не название термина.</small></div>`}<div class="audit-confidence"><b>Насколько уверен?</b><div>${[['sure','Проверил логикой'],['unsure','Не уверен'],['guess','Угадал']].map(([id,label])=>`<button data-act="audit-confidence" data-value="${id}" class="${audit.confidence===id?'chosen':''}">${label}</button>`).join('')}</div></div><p class="audit-note">Правильный ответ пока скрыт — диагностика не должна подсказывать следующий.</p>${btn('audit-submit',`Ответить ${svg('arrow',18)}`,'button studio-cta wide')}<button data-act="audit-skip" class="audit-skip">Не знаю — пропустить</button></div></main>`;
}
function finishAudit(){const result=analyzeAssessment(audit.questions,audit.answers);mastery.assessment={...result,at:new Date().toISOString(),questions:audit.questions.map(q=>q.id),answers:audit.answers};mastery.assessmentRuns=(mastery.assessmentRuns||0)+1;mastery.auditDraft=null;saveMastery();audit=null;go('auditResult');}
function renderAuditResult(){const r=mastery.assessment;if(!r)return renderHomeStudio();const weak=DOMAINS.filter(d=>(r.skills[d.id]??0)<65);return `<main class="view studio audit-results"><header class="studio-top">${brand()}<button class="mini-btn" data-act="go-home" aria-label="Закрыть">×</button></header><span class="studio-kicker"><i></i> ПРЕДВАРИТЕЛЬНАЯ ДИАГНОСТИКА</span><h1 class="studio-page-title">Понимание —<br><em>не угадывание.</em></h1><div class="audit-score-hero"><span>Доказанная уверенность в ответах</span><strong>${r.score}<small>/ 100</small></strong><div class="studio-progress"><span style="width:${r.score}%"></span></div><p>${r.correct} из 12 формально правильных. Угаданные ответы не равны освоению материала. Практическая квалификация не подтверждена.</p></div><div class="studio-section-top"><h2>Где работать дальше</h2><span>6 ОБЛАСТЕЙ</span></div><div class="audit-skill-list">${DOMAINS.map(d=>`<div><span><b>${esc(d.name)}</b><strong>${r.skills[d.id]}%</strong></span><div class="studio-progress"><span style="width:${r.skills[d.id]}%"></span></div></div>`).join('')}</div><div class="studio-recommend"><span class="studio-kicker"><i></i> СЛЕДУЮЩИЙ ШАГ</span><h3>${esc(recommendationV3().title)}</h3><p>${weak.length?'Начни с пробела в базовых навыках и подтверди его реальным заданием.':'Сильный тест — лишь сигнал: подтвердим его проверяемой работой.'}</p>${btn('audit-open-path','Открыть учебный этап ↗','button studio-cta wide')}</div><div class="studio-section-top"><h2>Разбор ответов</h2></div>${r.questions.map((id,i)=>{const q=PROBES.find(x=>x.id===id),ans=r.answers[i],g=gradeAttempt(q,ans);return `<div class="audit-review"><span class="${g.correct?'ok':'miss'}">${g.correct?'✓':'×'} ${esc(DOMAINS.find(d=>d.id===q.domain)?.name||'')}</span><b>${esc(q.text)}</b><p>${esc(q.explanation)}</p><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">Официальный материал ↗</a></div>`}).join('')}<button data-act="audit-start" class="studio-sub-action">Пройти другой вариант →</button></main>`;}
function startDojo(){const weakness=Object.fromEntries(DOMAINS.map(d=>[d.id,estimateSkill(d.id)??55])),qs=selectDailyDrill({day:today(),weakness,history:mastery.drillHistory||{},variant:state.selectedTrack+"/"+state.profile?.name});dojo={questions:qs,index:0,answers:[],left:90,paused:false,answered:false};go('dojo');runDojoTimer();}
function runDojoTimer(){clearInterval(dojoTimer);let prev=Date.now();dojoTimer=setInterval(()=>{if(!dojo||view!=='dojo')return;const now=Date.now();const delta=Math.min(1000,Math.max(0,now-prev))/1000;prev=now;if(dojo.paused||document.hidden)return;dojo.left=Math.max(0,dojo.left-delta);const n=document.querySelector('[data-dojo-time]');if(n)n.textContent=Math.ceil(dojo.left);const ring=document.querySelector('[data-dojo-ring]');if(ring)ring.style.setProperty('--ring',`${dojo.left/90*100}%`);if(dojo.left===0)finishDojo();},120)}
function finishDojo(){if(!dojo)return;clearInterval(dojoTimer);dojoTimer=null;const d=dojo,ids=d.questions;let correct=0;for(let i=0;i<ids.length;i++){const q=ids[i],a=d.answers[i];if(a!==undefined){const g=gradeAttempt(q,{value:a,confidence:'unsure'});if(g.correct)correct++;if(!mastery.drillScores)mastery.drillScores={};const rec=mastery.drillScores[q.domain]||{total:0,correct:0};rec.total++;if(g.correct)rec.correct++;mastery.drillScores[q.domain]=rec;mastery.drillHistory[q.id]=scheduleReview({id:q.id,correct:g.correct,old:mastery.drillHistory[q.id],day:today()});}}
 mastery.lastDrill={at:new Date().toISOString(),correct,total:ids.length,answered:d.answers.filter(x=>x!==undefined).length,seconds:Math.round(90-d.left)};mastery.drillCount=(mastery.drillCount||0)+1;saveMastery();dojo=null;go('dojoResult');}
function renderDojo(){if(!dojo)return renderHomeStudio();const q=dojo.questions[dojo.index],j=dojo.index,selected=dojo.answers[j];return `<main class="view studio studio-dojo"><div class="assessment-bar"><button class="round-close" data-act="dojo-exit">×</button><span>MORNING / MICRO SPRINT</span><b>${j+1} / ${dojo.questions.length}</b></div><div class="dojo-clock" data-dojo-ring style="--ring:${dojo.left/90*100}%"><div><strong data-dojo-time>${Math.ceil(dojo.left)}</strong><small>СЕКУНД</small></div></div><div class="studio-kicker"><i></i> ${esc(DOMAINS.find(d=>d.id===q.domain)?.name||'AI')}</div><h1 class="dojo-question">${esc(q.text)}</h1>${q.code?`<pre class="audit-code">${esc(q.code)}</pre>`:''}<div class="audit-answers">${q.options.map((a,i)=>`<button class="audit-opt ${selected===i?'chosen':''} ${dojo.answered&&i===q.answer?'success':''}" data-act="dojo-answer" data-choice="${i}" ${dojo.answered?'disabled':''}><span>${'ABCD'[i]}</span><strong>${esc(a)}</strong></button>`).join('')}</div>${dojo.answered?`<div class="dojo-feedback"><b>${selected===q.answer?'Верно.':'Разбор'}</b><p>${esc(q.explanation)}</p></div>${btn('dojo-next',`Следующее задание →`,'button studio-cta wide')}`:`<div class="dojo-hint">Выбирай ответ по смыслу. За случайное угадывание нет оценки освоения.</div>`}<button class="audit-skip" data-act="dojo-pause">${dojo.paused?'Продолжить':'Пауза'}</button>${dojo.paused?`<div class="dojo-pause-cover"><b>ПАУЗА</b><button data-act="dojo-pause" class="studio-cta">Продолжить →</button></div>`:''}</main>`}
function renderDojoResult(){const r=mastery.lastDrill||{correct:0,total:5,seconds:0};return `<main class="view studio"><header class="studio-top">${brand()}</header><span class="studio-kicker"><i></i> РАЗМИНКА ЗАВЕРШЕНА</span><h1 class="studio-page-title">Прокачка<br><em>каждый день.</em></h1><div class="audit-score-hero"><span>Сегодня верных ответов</span><strong>${r.correct}<small> / ${r.total}</small></strong><div class="studio-progress"><span style="width:${Math.round(100*r.correct/r.total)}%"></span></div><p>${r.answered} ответов · ${r.seconds} секунд. Ошибки появятся в будущих раундах чаще.</p></div>${btn('dojo-start',`Ещё один раунд ${svg('arrow',17)}`,'button studio-cta wide')}<button class="studio-sub-action" data-act="go-home">Вернуться к программе →</button></main>`}
function renderClinic(){const c=PROMPT_CLINIC.find(x=>x.id===clinicKey)||PROMPT_CLINIC[0],note=mastery.notes[c.id]||'',saved=!!mastery.clinics[c.id];return `<main class="view studio studio-clinic">${header('Prompt Lab')}<span class="studio-kicker"><i></i> WORKSHOP / REAL-WORLD TASKS</span><h1 class="studio-page-title">Мастерская<br><em>мышления.</em></h1><p class="studio-lead">Не выбирай ответ. Сам сформулируй решение, затем сравни с критериями и доработай.</p><div class="clinic-tabs">${PROMPT_CLINIC.map((x,i)=>`<button data-act="clinic-open" data-clinic="${x.id}" class="${c.id===x.id?'selected':''}">${String(i+1).padStart(2,'0')} ${esc(x.tag)}</button>`).join('')}</div><div class="clinic-brief"><span>ПРАКТИЧЕСКАЯ СИТУАЦИЯ</span><h2>${esc(c.title)}</h2><p>${esc(c.brief)}</p><div class="clinic-goal"><span>ЦЕЛЬ</span>${esc(c.goal)}</div></div><div class="studio-section-top"><h2>Твоё решение</h2><span>БЕЗ ПОДСКАЗОК</span></div><textarea id="clinic-note" class="studio-textarea" spellcheck="false" placeholder="Напиши свой промпт, инструкцию агенту или план проверки...">${esc(note)}</textarea><p class="studio-truth">Черновик сохраняется только на этом устройстве.</p>${btn('clinic-review',`Проверить по критериям ↗`,'button studio-cta wide')}${clinicReview?`<section class="clinic-rubric"><span class="studio-kicker"><i></i> РУБРИКА ПРОВЕРКИ</span><h3>Проверь свой ответ</h3><p>${esc(c.hint)}</p>${c.criteria.map((x,i)=>`<label><input type="checkbox" class="clinic-check"><span>${esc(x)}</span></label>`).join('')}<div class="studio-truth">Самооценка — не автоматическая проверка. Для настоящего подтверждения сделай тест или работающий артефакт.</div><button data-act="clinic-finish" class="button studio-cta wide">Сохранить разбор ↗</button></section>`:''}${saved?`<div class="studio-notice">✓ Эта работа сохранена как самостоятельная практика. Её можно улучшать.</div>`:''}</main>`}

function estimateSkill(id){
 const baseline=Number(mastery.assessment?.skills?.[id]??0),d=mastery.drillScores?.[id];
 if(!mastery.assessment)return null;
 if(!d?.total)return baseline;
 // Keep a small prior to avoid one streak of lucky answers generating 'mastery'.
 return Math.min(85,Math.round((baseline*2+d.correct*100)/(2+d.total)));
}

function renderCareer(){
 const p=normalizePersonal(personal),focus=FOCUSES.find(x=>x.id===p.focus),current=selectCurrentStep(p),total=p.completed.length,plan=makeDailyPlan(p.minutes),allDone=total===STEPS.length;
 return `<main class="view studio career-view">
 <header class="studio-top">${brand()}<button class="mini-btn" data-act="go-home" aria-label="Закрыть">${svg('close')}</button></header>
 <span class="studio-kicker"><i></i> СПЕЦИАЛИЗАЦИЯ / AI PRODUCT DEVELOPER</span>
 <h1 class="studio-page-title">Строить.<br><em>Проверять. Выпускать.</em></h1>
 <p class="studio-lead">Твой путь — создавать работающие AI-продукты, агентов и пайплайны. Тесты помогают вспомнить материал, но переход по этому маршруту подтверждай выполненной работой.</p>
 <div class="career-progress"><div><small>ПРАКТИЧЕСКИЕ ЭТАПЫ</small><strong>${total} <span>/ ${STEPS.length}</span></strong></div><div class="studio-progress"><span style="width:${100*total/STEPS.length}%"></span></div><small>Все этапы отмечаются только по твоему самоотчёту, не по автопроверке кода.</small></div>
 <div class="studio-section-top"><h2>Что хочешь создавать?</h2></div>
 <div class="career-focus-grid">${FOCUSES.map(f=>`<button class="career-focus ${f.id===p.focus?'active':''}" data-act="career-focus" data-value="${f.id}"><b>${esc(f.name)}</b><span>${esc(f.summary)}</span></button>`).join('')}</div>
 <div class="career-target"><small>ЦЕЛЕВОЙ ПРОЕКТ</small><b>${esc(focus.project)}</b><p>Один проект растёт вместе с твоими навыками: код, API, проверка, агенты и выпуск.</p></div>
 <div class="studio-section-top"><h2>Сколько времени сегодня?</h2></div>
 <div class="career-time">${[15,25,45].map(m=>`<button class="pill ${p.minutes===m?'selected':''}" data-act="career-minutes" data-value="${m}">${m} мин</button>`).join('')}</div>
 <div class="career-schedule">${plan.map((item,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${esc(item.name)}</b><strong>${item.minutes} мин</strong></div>`).join('')}</div>
 <div class="studio-section-top"><h2>${allDone?'Повтори и улучши проект':'Твой следующий шаг'}</h2></div>
 <article class="career-current"><div class="career-stage-top"><span>${esc(current.skill)} · ${esc(current.duration)}</span><span>УРОВЕНЬ ПО РЕАЛЬНОЙ ПРАКТИКЕ</span></div><h2>${esc(current.name)}</h2><p>${esc(current.task)}</p><div class="career-result"><b>Что показать в результате</b><span>${esc(current.deliverable)}</span></div><div class="career-checks">${current.checks.map(c=>`<div>◈ &nbsp; ${esc(c)}</div>`).join('')}</div><a class="career-source" href="${esc(current.source)}" target="_blank" rel="noopener noreferrer">Первичный материал · ${esc(current.publisher)} ↗</a>${allDone?'':`<label class="field-label" for="career-proof">После выполнения: файл, команда запуска и результат проверки</label><textarea class="studio-textarea" id="career-proof" rows="5" placeholder="Пример: checker.py — проверил 7 assert; команда python checker.py; вывод без ошибок... (не отмечай заранее)"></textarea><button class="button studio-cta wide" data-act="career-proof">Сохранить свой результат ↗</button><p class="studio-truth">Запись не является независимой проверкой. Реальные тесты и код нужно предъявить и проверить отдельно.</p>`}</article>
 <div class="studio-section-top"><h2>Вся карта компетенций</h2></div>
 <div class="career-steps">${STEPS.map((step,i)=>`<div class="career-step ${p.completed.some(c=>c.id===step.id)?'done':''}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(step.name)}</b><small>${esc(step.deliverable)}</small></div><em>${p.completed.some(c=>c.id===step.id)?'САМООТЧЁТ':'ВПЕРЕДИ'}</em></div>`).join('')}</div>
 <p class="studio-truth">Публикуется только общая программа. Твой выбор и записи хранятся локально на устройстве; используй экспорт в настройках для резервной копии.</p>
 </main>${nav('library')}`;
}

function renderStatsStudio(){
 const t=track(),count=t.modules.filter(m=>hasPracticeEvidence(coach,t.id,m.id)).length,
 quiz=state.stats.answered?Math.round(100*state.stats.correct/state.stats.answered):0;
 return `<main class="view studio studio-skills"><header class="studio-top">${brand()}<button class="mini-btn" data-act="settings" aria-label="Настройки">${svg('settings')}</button></header><span class="studio-kicker"><i></i> ДАННЫЕ, А НЕ ОБЕЩАНИЯ</span><h1 class="studio-page-title">Карта<br><em>навыков.</em></h1><p class="studio-lead">Отдельно показываем результаты тестов, ежедневной практики и самостоятельных проектов. Они не равнозначны.</p><div class="studio-skill-counters"><div><small>ПРАКТИКИ</small><strong>${count}<i>/${t.modules.length}</i></strong><span>самостоятельно отмечено</span></div><div><small>СПРИНТЫ</small><strong>${mastery.drillCount||0}</strong><span>коротких сессий</span></div><div><small>ТЕСТЫ</small><strong>${quiz}%</strong><span>правильных ответов в раундах</span></div></div>
 <div class="studio-section-top"><h2>Предварительные навыки</h2><button data-act="audit-start" class="plain-link">Перепроверить ↗</button></div><div class="audit-skill-list">${DOMAINS.map(d=>{const n=estimateSkill(d.id);return `<div><span><b>${esc(d.name)}</b><strong>${n===null?'Нет данных':n+'%'}</strong></span><div class="studio-progress"><span style="width:${n??0}%"></span></div></div>`}).join('')}</div><p class="studio-truth">Это оценка по локальным задачам и самоуверенности, а не профессиональный рейтинг. Чтобы подтвердить навыки, нужны реальные тесты и проекты.</p>
 <div class="studio-section-top"><h2>Портфолио</h2><button data-act="nav" data-to="library" class="plain-link">Этапы ↗</button></div>${count?t.modules.filter(m=>hasPracticeEvidence(coach,t.id,m.id)).map(m=>`<button class="studio-portfolio" data-act="open-lab" data-module="${m.id}"><span>✓</span><b>${esc(m.title)}</b><small>Самостоятельная запись, не автопроверка</small>↗</button>`).join(''):`<div class="studio-empty"><span>✧</span><b>Первый проект ещё впереди.</b><p>Добавь не просто галочку, а ссылку на код, выполненные тесты и свой разбор.</p>${btn('open-lab','Начать с первого задания ↗','button small outline',`data-module="${t.modules[0].id}"`)}</div>`}
 ${mastery.lastDrill?`<div class="studio-section-top"><h2>Последняя разминка</h2></div><div class="studio-notice">${mastery.lastDrill.correct} / ${mastery.lastDrill.total} верных · ${mastery.lastDrill.seconds} секунд. Слабые темы будут повторяться.</div>`:''}
 </main>${nav('stats')}`;
}

document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,mode=el.dataset.mode,mod=el.dataset.module;switch(act){

case 'career-open':go('career');break;
case 'career-focus':personal=normalizePersonal({...personal,focus:el.dataset.value});savePersonal();render();break;
case 'career-minutes':personal=normalizePersonal({...personal,minutes:Number(el.dataset.value)});savePersonal();render();break;
case 'career-proof':try{personal=submitEvidence(personal,selectCurrentStep(personal).id,$('#career-proof')?.value||'');savePersonal();toast('Записан самоотчёт. Проверка кода остаётся за тобой.');render();}catch(err){toast(err.message||'Нужно доказательство выполненной работы')}break;
case 'audit-start':startAudit();break;
case 'audit-exit':audit=null;mastery.auditDraft=null;saveMastery();go('home');break;
case 'audit-choice':if(audit){audit.value=Number(el.dataset.choice);render();}break;
case 'audit-confidence':if(audit){audit.confidence=el.dataset.value;render();}break;
case 'audit-skip':if(audit){audit.answers[audit.index]={value:null,confidence:'unsure'};audit.index++;if(audit.index>=audit.questions.length)finishAudit();else{audit.value=null;audit.confidence='unsure';mastery.auditDraft={seed:audit.seed,index:audit.index,answers:audit.answers};saveMastery();render();}}break;
case 'audit-submit':if(audit){let value=audit.value;if(audit.questions[audit.index].type==='short')value=$('#audit-input')?.value?.trim()??'';if(value===null||value===undefined||String(value).trim()===''){toast('Выбери ответ или нажми «Не знаю»');break;}audit.answers[audit.index]={value,confidence:audit.confidence};audit.index++;if(audit.index>=audit.questions.length)finishAudit();else{audit.value=null;audit.confidence='unsure';mastery.auditDraft={seed:audit.seed,index:audit.index,answers:audit.answers};saveMastery();render();}}break;
case 'audit-open-path':{lessonModule=recommendationV3().id;go('lesson');break;}
case 'dojo-start':startDojo();break;
case 'dojo-exit':if(dojo){dojo=null;clearInterval(dojoTimer);dojoTimer=null;}go('home');break;
case 'dojo-answer':if(dojo&&!dojo.answered&&!dojo.paused){dojo.answers[dojo.index]=Number(el.dataset.choice);dojo.answered=true;render();}break;
case 'dojo-next':if(dojo){dojo.index++;dojo.answered=false;if(dojo.index>=dojo.questions.length)finishDojo();else render();}break;
case 'dojo-pause':if(dojo){dojo.paused=!dojo.paused;render();}break;
case 'clinic-open':clinicKey=el.dataset.clinic||PROMPT_CLINIC[0].id;clinicReview=false;go('clinic');break;
case 'clinic-review':{const note=$('#clinic-note')?.value?.trim()||'';if(note.length<70){toast('Нужно конкретное решение: хотя бы 70 символов');break;}mastery.notes[clinicKey]=note;saveMastery();clinicReview=true;render();break;}
case 'clinic-finish':{const checks=[...document.querySelectorAll('.clinic-check')];const count=checks.filter(x=>x.checked).length;if(count<checks.length){toast('Проверь все критерии. Исправь ответ при необходимости');break;}mastery.clinics[clinicKey]={at:new Date().toISOString(),selfReviewed:true,note:mastery.notes[clinicKey]};saveMastery();clinicReview=false;toast('Самостоятельная работа сохранена');render();break;}
case 'diagnostic-start':startAudit();break;
case 'diagnostic-exit':assessment=null;go('home');break;
case 'diagnostic-answer':{if(!assessment||assessment.feedback!==null)break;const answer=Number(el.dataset.choice);assessment.answers[assessment.index]=answer;assessment.feedback={answer};render();break;}
case 'diagnostic-next':{if(!assessment||assessment.feedback===null)break;if(assessment.index===DIAGNOSTIC.length-1){const r=analyzePlacement(assessment.answers,state.selectedTrack||'builder');coach.placement=r;coach.skills={...r.skills};coach.skillSamples=Object.fromEntries(SKILLS.map(sk=>[sk.id,2]));saveCoach();assessment=null;go('diagnosticResult');}else{assessment.index++;assessment.feedback=null;render();}break;}
case 'go-recommended':{const t=track();lessonModule=t.modules[Math.min(coach.placement?.recommended??0,t.modules.length-1)].id;go('lesson');break;}
case 'open-lab':labModule=mod;go('lab');break;
case 'lab-save':{const note=$('#lab-note')?.value||'';try{coach=applyPracticeEvidence(coach,{track:track().id,module:labModule||currentModule().id,note});saveCoach();toast('Практика записана. Продолжай проверять себя.');render();}catch(err){toast(err.message||'Не удалось сохранить');}break;}
case 'onb-next':onbStep=Math.min(2,onbStep+1);render();break;
case 'onb-back':onbStep=Math.max(0,onbStep-1);render();break;
case 'choose-onb':draft.track=el.dataset.track;render();break;
case 'set-level':draft.level=el.dataset.value;render();break;
case 'set-minutes':draft.minutes=Number(el.dataset.value);render();break;
case 'finish-onb':finishOnboarding();break;
case 'nav':go(el.dataset.to);break;
case 'settings':go('settings');break;
case 'choose-track':selectTrack(el.dataset.track);break;
case 'open-lesson':lessonModule=mod;go('lesson');break;
case 'back':exitBack();break;
case 'start':start(mode,mod);break;
case 'answer':answer(Number(el.dataset.choice));break;
case 'next':next();break;
case 'freeze':if(session&&!session.paused&&!session.feedback&&session.freezes>0){session.freezes--;session.freezeMs=4000;activeSave();render();}break;
case 'leave-game':modal='leave';if(session)session.paused=true;activeSave();render();break;
case 'modal-resume':modal=null;if(session)session.paused=false;lastTick=Date.now();render();break;
case 'modal-quit':saveAndQuit();break;
case 'modal-cancel':modal=null;render();break;
case 'resume-game':pauseResume();break;
case 'quit-game':saveAndQuit();break;
case 'resume':{const s=recoverSession();if(!s){toast('Не удалось восстановить сессию');return;}session=s;resumeAvailable=null;go('game');startClock();break;}
case 'go-home':go('home');break;
case 'retry':start(lastResult.mode,lastResult.module);break;
case 'toggle-sound':state.settings.sound=!state.settings.sound;save();render();break;
case 'toggle-motion':state.settings.reduceMotion=!state.settings.reduceMotion;document.documentElement.style.setProperty('scroll-behavior',state.settings.reduceMotion?'auto':'smooth');save();render();break;
case 'export':exportData();break;
case 'import':$('#fileImport')?.click();break;
case 'confirm-reset':modal='reset';render();break;
case 'reset-yes':localStorage.removeItem(PERSONAL_KEY);personal=normalizePersonal(null);localStorage.removeItem(KEY);localStorage.removeItem(ACTIVE);state=normalizeState(null);onbStep=0;draft={name:'',track:'builder',level:'beginner',minutes:15};coach=normalizeCoach(null);localStorage.removeItem(COACH_KEY);mastery=mkEmpty();saveMastery();session=null;resumeAvailable=null;modal=null;go('onboard');break;
}});
document.addEventListener('change',async e=>{if(e.target.id==='minutes'){state.profile.minutes=Number(e.target.value);save();toast('Настройки сохранены');}if(e.target.id==='fileImport'){try{const f=e.target.files?.[0];if(!f)return;const txt=await f.text();state=parseBackup(txt);try{const data=JSON.parse(txt);coach=normalizeCoach(data.coach);mastery={...mkEmpty(),...(data.mastery||{})};saveMastery();personal=normalizePersonal(data.personal);savePersonal()}catch{coach=normalizeCoach(null)}saveCoach();save();localStorage.removeItem(ACTIVE);resumeAvailable=null;go('home');toast('Прогресс восстановлен');}catch(err){toast(err.message||'Не удалось открыть файл');}}});
document.addEventListener('input',e=>{if(e.target.id==='nick')draft.name=e.target.value;if(e.target.id==='audit-input'&&audit)audit.value=e.target.value;if(e.target.id==='clinic-note'){mastery.notes[clinicKey]=e.target.value;saveMastery();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&dojo)dojo.paused=true;if(document.hidden&&session&&view==='game'){session.paused=true;activeSave();}else if(!document.hidden&&session&&view==='game'){lastTick=Date.now();render();}});
document.addEventListener('keydown',e=>{if(view==='game'&&session&&!session.paused&&document.activeElement?.tagName!=='INPUT'){const idx=({1:0,2:1,3:2,a:0,b:1,c:2})[e.key.toLowerCase()];if(idx!==undefined){e.preventDefault();answer(idx)}if(e.key===' '&&session.feedback&&['learn','review'].includes(session.mode)){e.preventDefault();next()}}});
render();
if('serviceWorker' in navigator && location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
